import{_ as a,o as r,c as e,a6 as l}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"RSI 技术探究","description":"用大白话由浅入深地讲“递归自我改进”（RSI）：AI 怎样自己出题、自己打分、改自己的代码、发明算法、参与造下一代 AI，进展怎么量、卡在哪、实验室又为它设了哪些红线。","frontmatter":{"title":"RSI 技术探究","description":"用大白话由浅入深地讲“递归自我改进”（RSI）：AI 怎样自己出题、自己打分、改自己的代码、发明算法、参与造下一代 AI，进展怎么量、卡在哪、实验室又为它设了哪些红线。","source":"https://daiw.org/manual/rsi"},"headers":[],"relativePath":"manual/llm/rsi/index.md","filePath":"manual/llm/rsi/index.md"}'),n={name:"manual/llm/rsi/index.md"};function o(s,t,i,d,h,g){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="rsi-技术探究" tabindex="-1">RSI 技术探究 <a class="header-anchor" href="#rsi-技术探究" aria-label="Permalink to &quot;RSI 技术探究&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/rsi" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David（道雾轩） · 原文更新于 2026-11-06</p></blockquote><blockquote><p>用大白话由浅入深地讲“递归自我改进”（RSI）：AI 怎样自己出题、自己打分、改自己的代码、发明算法、参与造下一代 AI，进展怎么量、卡在哪、实验室又为它设了哪些红线。</p></blockquote><h2 id="序-·-当-ai-开始参与造-ai" tabindex="-1">序 · 当 AI 开始参与造 AI <a class="header-anchor" href="#序-·-当-ai-开始参与造-ai" aria-label="Permalink to &quot;序 · 当 AI 开始参与造 AI&quot;">​</a></h2><p>1965 年，数学家 I. J. Good 设想过一台“超智能机器”：既然设计机器本身就是一种智力活动，一台比人更聪明的机器就能设计出更好的机器——然后是一场“智能爆炸”。半个多世纪里，这只是思想实验。</p><p>到了 2026 年，它开始有了工程上的影子。2 月 5 日，OpenAI 在 GPT-5.3-Codex 的发布说明里写道，这是他们第一个“instrumental in creating itself”（参与创造了自己）的模型：早期版本被用来监控和调试这次发布的训练运行、优化包在自己外面的 Agent 程序、在发布期间动态扩缩 GPU 集群——干的是造模型流程里的工程活，拍板的仍是人。各家前沿实验室陆续公开类似的内部数据，研究论文数量也在这一年陡增。这个方向有个名字：<strong>RSI（Recursive Self-Improvement，递归自我改进）</strong>——AI 系统参与改进“造 AI 的流程”，乃至它自己的下一代。</p><p>这个专栏用大白话，从“它到底是什么意思”讲到“它现在走到了哪一步、为什么还没失控加速、谁在给它设护栏”。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>资料说明</strong>：本专栏成文于 <strong>2026 年 9 月</strong>，并于 <strong>2026 年 11 月初</strong>复核，以论文（arXiv 等）、实验室官方博客、系统卡与安全框架原文为主要依据。实验室与论文作者自述、尚无第三方复现的数字，正文标“官方口径”或“作者报告”；媒体与二手解读注明出处。RSI 是一个每周都有新论文的方向，读时请留意各处标注的时间点。</p></div><h2 id="先看全貌-五级台阶" tabindex="-1">先看全貌：五级台阶 <a class="header-anchor" href="#先看全貌-五级台阶" aria-label="Permalink to &quot;先看全貌：五级台阶&quot;">​</a></h2><p>“AI 改进自己”听起来像一件事，其实是一串由浅到深的台阶，本书就按这个顺序展开：</p><table tabindex="0"><thead><tr><th>台阶</th><th>改的是什么</th><th>通俗说法</th><th>对应篇目</th></tr></thead><tbody><tr><td>1</td><td>单次的答案</td><td>写完再检查一遍</td><td><a href="/Front2Full/manual/llm/rsi/rsi-ladder">五级台阶</a></td></tr><tr><td>2</td><td>训练信号</td><td>自己出题、自己打分</td><td><a href="/Front2Full/manual/llm/rsi/self-play-data">自博弈与合成数据</a>、<a href="/Front2Full/manual/llm/rsi/self-rewarding">自我奖励</a></td></tr><tr><td>3</td><td>脚手架与代码</td><td>改写自己的工具和流程</td><td><a href="/Front2Full/manual/llm/rsi/self-modifying-agents">改自己的代码</a></td></tr><tr><td>4</td><td>研发环节</td><td>发明算法、跑实验、调基础设施</td><td><a href="/Front2Full/manual/llm/rsi/algorithm-discovery">AlphaEvolve 一族</a>、<a href="/Front2Full/manual/llm/rsi/automated-research">自动化 AI 研发</a></td></tr><tr><td>5</td><td>整个研究闭环</td><td>自己提想法、验证、造出下一代</td><td><a href="/Front2Full/manual/llm/rsi/automated-research">自动化 AI 研发</a></td></tr></tbody></table><p>越往上，改动的影响越大，验收也越难——这是贯穿全书的一条线索。</p><h2 id="这个专栏怎么走" tabindex="-1">这个专栏怎么走 <a class="header-anchor" href="#这个专栏怎么走" aria-label="Permalink to &quot;这个专栏怎么走&quot;">​</a></h2><p><strong>第 0 部分 · 先搞懂概念</strong></p><ul><li><strong>RSI 是什么</strong> —— 从 1965 年的“智能爆炸”、哥德尔机讲到 2026 年实验室的表态。</li><li><strong>五级台阶</strong> —— 把“自我改进”拆成五级：每级改什么、谁来验收、2026 年走到哪一步。</li></ul><p><strong>第 1 部分 · 自己教自己</strong></p><ul><li><strong>自己出题自己练</strong> —— 从 AlphaGo Zero 的左右互搏，到大模型零数据自训练、合成数据飞轮与模型坍塌。</li><li><strong>自己当裁判</strong> —— 奖励从哪来：人类打分、AI 打分、自我奖励、可验证奖励，以及绕不开的奖励黑客。</li></ul><p><strong>第 2 部分 · 自己改自己</strong></p><ul><li><strong>改自己的代码</strong> —— 哥德尔机的“先证明再改”与达尔文哥德尔机的“先试再留”，档案库为何胜过贪心。</li><li><strong>让 AI 发明算法</strong> —— FunSearch 到 AlphaEvolve 再到 2026 年的开源与上云，这套循环怎样反哺 AI 自己。</li><li><strong>自动化 AI 研发</strong> —— 按研发流程逐段拆开：哪些环节已交给 AI，哪些仍由人拍板。</li></ul><p><strong>第 3 部分 · 量尺、瓶颈与护栏</strong></p><ul><li><strong>怎么量进展</strong> —— METR 的任务时间跨度、实验室的研发评测，以及直接量“研发加速”的新指标。</li><li><strong>为什么还没“爆炸”</strong> —— 算力、验证、数据、研究品味与收益递减，乐观派与怀疑派并排摆。</li><li><strong>风险与治理</strong> —— 各家实验室安全框架里为“AI 自动化 AI 研发”设的阈值，以及监控与对齐的难点。</li></ul><p>最后一篇<strong>回顾与展望</strong>把全书串起来。</p><h2 id="和站内其他专栏的关系" tabindex="-1">和站内其他专栏的关系 <a class="header-anchor" href="#和站内其他专栏的关系" aria-label="Permalink to &quot;和站内其他专栏的关系&quot;">​</a></h2><p>想先补大模型本身的底子，可以读<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">《AI 大模型解构》</a>；想看 2026 年前沿开源旗舰是怎样在后训练里落地自反馈强化学习与大规模可验证环境的，见<a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a>、<a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a>与<a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a>；想看 Agent 是怎么从一个模型搭起来的，见<a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">《从 LLM 到 Coding Agent》</a>。同期另一条前沿方向——不写字、只给决策的 System One 模型——见<a href="https://daiw.org/manual/jev" target="_blank" rel="noreferrer">《Jev 原理与应用》</a>。</p><p>准备好了，就从 <a href="/Front2Full/manual/llm/rsi/what-is-rsi">RSI 是什么</a> 开始。</p>',25)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
